# Сборка 05_итог.md из реестра, DEF, указателя структур и проверки ссылок
import json, re
from collections import Counter
from openpyxl import load_workbook
from build_matrix import DEF
reg={r['№']:r for r in json.load(open('registry.json'))}
idx=json.load(open('s5_index.json')); chk=json.load(open('s5_refcheck.json'))
K=[('займ','1','Договор займа (кредита, микрокредита, бюджетного кредита)'),('залог','2','Договор залога'),('гарантия','3','Договор гарантии (по содержанию — солидарное поручительство)'),('поручение','4','Договор поручения (агентский) МИО — агент'),('дкп','5','Договор купли-продажи предмета лизинга'),('лизинг','6','Договор финансового лизинга')]
ws=load_workbook('../02_вопросы_на_решение.xlsx')['Вопросы на решение']
Q=[r for r in ws.iter_rows(min_row=2,values_only=True)]
L=[]; A=L.append
A(open('s5_part1.md').read())
A('\n## 2. Какие исходные договоры относятся к каждому типу\n')
for k,n,name in K:
    A(f'\n### 2.{n}. {name}\n\n| № | Регион | Файл | Статус | Часть файла |\n|---|---|---|---|---|')
    for c in DEF[k]:
        num=int(re.match(r'№(\d+)',c['label']).group(1)); r=reg[num]
        part=c['label'].split(',',1)[1].strip() if ',' in c['label'] else ''
        note=' (справочно, другая программа)' if (k=='гарантия' and num==46) else ''
        A(f"| {num} | {r['регион']} | {r['путь к файлу'].split('/')[-1]} | {r['статус']}{note} | {part} |")
    if k=='поручение': A('| 36 | 10. Кызылординская область | Договор поручения каз.doc | заполненный экземпляр | казахская версия №35 — только для сверки |')
A('\nНе входят ни в один тип: №39–42 (приложения к договору поручения Кызылорды, «СОМНЕВАЕМСЯ», см. 03, 4.8) и дубликаты №44, 56, 60, 62, 64, 66.\n')
A(open('s5_part2.md').read())
A('\n## 6. Перечень положений и их источники\n\nПолный перечень пунктов итоговых договоров с источником каждого пункта — в файлах `04_структура_<тип>.md`: у каждого пункта указаны номер исходного договора (по реестру) и пункт. Ниже — сводный указатель по разделам (автоматически по ссылкам в `04_*`): какие исходные договоры этого типа использованы в разделе (ссылки на связанные договоры других типов — в самих `04_*`) и сколько в нём вариативных, региональных пунктов и отмеченных дефектов источника.\n')
for k,n,name in K:
    d=idx[k]; t=d['total']
    A(f"\n### 6.{n}. {name} — `04_структура_{k}.md`\n\nВсего: меток [ВАРИАНТ] — {t['variants']}, [РЕГИОНАЛЬНОЕ] — {t['regional']}, [ДЕФЕКТ ИСТОЧНИКА] — {t['defects']}; разных номеров вопросов реестра в пометках «вопрос №X» — {len(t['questions'])}.\n\n| Раздел структуры | Источники (№ реестра) | ВАРИАНТ | РЕГИОН. | ДЕФЕКТ |\n|---|---|---|---|---|")
    for r in d['rows']:
        A(f"| {r['section'][:80]} | {', '.join(map(str,r['sources'])) or '—'} | {r['variants']} | {r['regional']} | {r['defects']} |")
A('\n## 7. Выборочная проверка ссылок\n\nПроверено 12 ссылок из `04_структура_*.md`, по две на каждый тип. Выбор случайный с фиксированным зерном (скрипт `tmp/s5_refcheck.py`). Цитата искалась в текстовой копии именно того договора, на который дана ссылка.\n\n| № | Тип | Ссылка в структуре | Цитата (начало) | Результат |\n|---|---|---|---|---|')
manual={'№53':'подтверждено вручную: цитата относится к №48, №49, №58, №24 (п. 2.3.1) и найдена в их текстах; скрипт ошибочно взял соседнюю ссылку «№53» из того же абзаца. Ошибка скрипта, не структуры',
        '№15':'подтверждено: цитата сокращена («…»), найдена в тексте №15 по частям',
        '№65':'подтверждено: цитата сокращена («…»), обе части найдены в тексте №65'}
for i,x in enumerate(chk,1):
    res='найдено дословно' if x['ok'] else manual.get(f"№{x['n']}",'не подтверждено')
    A(f"| {i} | {x['type']} | №{x['n']} {x['ref'][:60]} | «{x['quote'][:80]}…» | {res} |")
A('\n**Итог проверки:** 12 из 12 ссылок подтверждены. 9 — автоматически дословно; 2 — сокращённые цитаты, подтверждены по частям; 1 — подтверждена вручную (ошибка извлечения ссылки скриптом). Проверки этапа 3 (14 ссылок) — в `03_унификация.md`, раздел 9.\n')
open('../05_итог.md','w').write('\n'.join(L)); print('ok', sum(len(x) for x in L))
